# A classical model with an arrow from Alice's setting x to Bob's outcome b (Wood-Spekkens style).
F = math.sin(math.pi / 8) ** 2

def model(eps):
    """lambda ~ Bernoulli(1/2 + eps) for value 0; a = lambda; b = lambda XOR (x AND y) XOR nu, nu ~ Bernoulli(F)."""
    p = {}
    for x, y, a, b in itertools.product((0, 1), repeat=4):
        p[x, y, a, b] = sum((0.5 + eps if lam == 0 else 0.5 - eps) * (1 - F if nu == 0 else F)
                            for lam in (0, 1) for nu in (0, 1) if a == lam and b == lam ^ (x & y) ^ nu)
    return p

for eps in (0.0, 0.05, 0.1, 0.2):
    p = model(eps)
    E = {(x, y): sum((-1) ** (a ^ b) * p[x, y, a, b] for a in (0, 1) for b in (0, 1)) for x in (0, 1) for y in (0, 1)}
    S = E[0, 0] + E[0, 1] + E[1, 0] - E[1, 1]
    pb = lambda x, y: sum(p[x, y, a, 0] for a in (0, 1))
    pa = lambda x, y: sum(p[x, y, 0, b] for b in (0, 1))
    print(f"eps = {eps:.2f}: S = {S:.4f}  p(b=0|x=0,y=1) - p(b=0|x=1,y=1) = {pb(0, 1) - pb(1, 1):.4f}"
          f" (sqrt2*eps = {math.sqrt(2) * eps:.4f});  Alice: p(a=0|x=0,y=0) - p(a=0|x=0,y=1) = {pa(0, 0) - pa(0, 1):.1f}")

